func resolveClass(r rune) BreakClass {
	class := Class(r)
	switch class {
	case ClassAI, ClassSG, ClassXX:
		class = ClassAL
	case ClassCJ:
		class = ClassNS
	case ClassSA:
		if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r) {
			class = ClassCM
		} else {
			class = ClassAL
		}
	case ClassCB:
		class = ClassID
	}
	return class
}

